   813	\begin{proposition}[Characterization of isogenies]
   814	\label{prop:milne-isogeny-characterization}
   815	
   816	\dcref{MI:ch1:7.1}
   817	\uses{def:milne-isogeny,thm:milne-abelian-projective}
   818	For a homomorphism $\alpha:A\to B$ of abelian varieties, the following are
   819	equivalent:
   820	\begin{enumerate}
   821	\item $\alpha$ is an isogeny;
   822	\item $\dim A=\dim B$ and $\alpha$ is surjective;
   823	\item $\dim A=\dim B$ and $\ker(\alpha)$ is finite;
   824	\item $\alpha$ is finite, flat, and surjective.
   825	\end{enumerate}
   826	\end{proposition}
   827	
   828	\begin{proof}
   829	Because $A$ is complete, $\alpha(A)$ is closed in $B$.  Translation by a point
   830	of $\alpha(A)$ identifies every fibre over $\alpha(A)$ with the fibre over
   831	$0$.  The fibre-dimension theorem therefore gives
   832	\[
   833	 \dim\ker(\alpha)=\dim A-\dim\alpha(A).
